struct ME_M3_IntInt { int64_t key; int64_t val; uint64_t hash; bool live; };
/* Small maps (up to VU_SMALL_MAP entries) have no index: a scan comparing keys beats hashing them.
   Bigger maps hash with SipHash and probe an index into the entries. */
static int64_t vu_mfind_M3_IntInt(const M3_IntInt *m, const int64_t *k) {
    if (!m->nidx) {
        for (int64_t i = 0; i < m->nents; i++) {
            const ME_M3_IntInt *en = &m->ents[i];
            if (en->live && (en->key == *k)) return i;
        }
        return -1;
    }
    uint64_t h = vu_hash_int((int64_t)*k);
    uint64_t mask = (uint64_t)m->nidx - 1;
    for (uint64_t i = h & mask;; i = (i + 1) & mask) {
        int64_t e = m->idx[i];
        if (e == 0) return -1;
        const ME_M3_IntInt *en = &m->ents[e - 1];
        if (en->live && en->hash == h && (en->key == *k)) return e - 1;
    }
}
static void vu_mindex_M3_IntInt(M3_IntInt *m, int64_t want) {
    int64_t j = 0;
    for (int64_t i = 0; i < m->nents; i++) if (m->ents[i].live) m->ents[j++] = m->ents[i];
    m->nents = j;
    int64_t n = 8;
    while (n < want) { if (n > INT64_MAX / 4) vu_oom(); n *= 2; }
    free(m->idx);
    m->idx = (int64_t *)calloc((size_t)n, sizeof(int64_t));
    if (!m->idx) vu_oom();
    m->nidx = n;
    for (int64_t i = 0; i < m->nents; i++) {
        uint64_t s = m->ents[i].hash & ((uint64_t)n - 1);
        while (m->idx[s]) s = (s + 1) & ((uint64_t)n - 1);
        m->idx[s] = i + 1;
    }
}
static void vu_mbig_M3_IntInt(M3_IntInt *m) {
    for (int64_t i = 0; i < m->nents; i++) {
        ME_M3_IntInt *en = &m->ents[i];
        if (!en->live) continue;
        const int64_t *k = &en->key;
        en->hash = vu_hash_int((int64_t)*k);
    }
    vu_mindex_M3_IntInt(m, (m->live + 1) * 2);
}
static void vu_mput_M3_IntInt(M3_IntInt *m, int64_t *k, int64_t v, bool take) {
    int64_t e = vu_mfind_M3_IntInt(m, k);
    if (e >= 0) { ME_M3_IntInt *en = &m->ents[e];  en->val = v; if (take) {  } return; }
    if (!m->nidx) {
        if (m->nents >= VU_SMALL_MAP) vu_mbig_M3_IntInt(m);
    } else if ((m->nents + 1) * 4 > m->nidx * 3) vu_mindex_M3_IntInt(m, (m->live + 1) * 2);
    uint64_t h = m->nidx ? vu_hash_int((int64_t)*k) : 0;
    if (m->nents == m->cap) {
        if (m->cap > (int64_t)(PTRDIFF_MAX / sizeof(ME_M3_IntInt) / 2)) vu_oom();
        /* 4 entries first (most objects are small), then 12, so a typical record grows once; then 1.5x. */
        int64_t c = m->cap == 0 ? 4 : m->cap == 4 ? 12 : m->cap + m->cap / 2;
        ME_M3_IntInt *d = (ME_M3_IntInt *)realloc(m->ents, (size_t)c * sizeof(ME_M3_IntInt));
        if (!d) vu_oom();
        m->ents = d;
        m->cap = c;
    }
    ME_M3_IntInt *en = &m->ents[m->nents];
    en->key = take ? *k : *k; en->val = v; en->hash = h; en->live = true;
    m->nents++;
    m->live++;
    if (m->nidx) {
        uint64_t mask = (uint64_t)m->nidx - 1, s = h & mask;
        while (m->idx[s]) s = (s + 1) & mask;
        m->idx[s] = m->nents;
    }
}
